use lg_cli::args::parse_args;
use lg_cli::Settings;
use lg_parse::Config;

#[test]
fn disc_l07() {
    let file = Config::parse("[report]\nlocale = pt-BR\ncurrency = BRL\n").unwrap();
    let args: Vec<String> = ["--locale", "en-US", "categories", "x.csv"].iter().map(|s| s.to_string()).collect();
    let inv = parse_args(&args).unwrap();
    let s = Settings::resolve(&file, &inv.flags).unwrap();
    assert_eq!(s.locale.tag, "en-US");
    assert_eq!(Settings::resolve(&file, &Default::default()).unwrap().locale.tag, "pt-BR");
}
